483	  background: none;
484	  border: 0;
485	  padding: 0;
486	}
487	.prose .anchor {
488	  position: absolute;
489	}
490	
491	/* sugar-high — four roles, no rainbow */
492	.prose pre .sh__token--keyword,
493	.prose pre .sh__token--sign {
494	  color: var(--accent);
495	}
496	.prose pre .sh__token--string,
