508	/* ---------------------------------------------------------------------------
509	   Command palette
510	--------------------------------------------------------------------------- */
511	
512	@keyframes palette-in {
513	  from {
514	    opacity: 0;
515	    transform: translateY(8px) scale(0.985);
516	  }
517	  to {
518	    opacity: 1;
519	    transform: none;
520	  }
521	}
522	
523	.palette-panel {
