529	  background: color-mix(in oklab, var(--background) 62%, transparent);
530	  backdrop-filter: blur(6px);
531	}
532	
533	/* ---------------------------------------------------------------------------
534	   Reduced motion: movement goes, colour feedback stays.
535	--------------------------------------------------------------------------- */
536	
537	@media (prefers-reduced-motion: reduce) {
538	  html {
539	    scroll-behavior: auto;
540	  }
541	  *,
542	  *::before,
543	  *::after {
544	    animation-duration: 0.001ms !important;
545	    animation-delay: 0ms !important;
546	    animation-iteration-count: 1 !important;
