16	  function moveLight(clientX: number, clientY: number) {
17	    const slot = slotRef.current;
18	    if (!slot) return;
19	    const rect = slot.getBoundingClientRect();
20	    slot.style.setProperty(
21	      "--lx",
22	      `${((clientX - rect.left) / rect.width) * 100}%`,
23	    );
24	    slot.style.setProperty(
25	      "--ly",
26	      `${((clientY - rect.top) / rect.height) * 100}%`,
27	    );
28	    slot.style.setProperty("--lit", "1");
29	  }
30	
31	  return (
32	    <section
33	      className="reveal pt-14 sm:pt-20"
34	      onPointerMove={(event) => moveLight(event.clientX, event.clientY)}
35	      onPointerLeave={() => slotRef.current?.style.setProperty("--lit", "0")}
36	    >
37	      <div className="flex items-center gap-4" style={{ "--i": 0 } as React.CSSProperties}>
38	        <div ref={slotRef} className="avatar-slot size-14 shrink-0 sm:size-16">
