9	const noSubscribe = () => () => {};
10	
11	export function ThemeToggle() {
12	  const { resolvedTheme, setTheme } = useTheme();
13	  const mounted = useSyncExternalStore(
14	    noSubscribe,
15	    () => true,
16	    () => false,
17	  );
18	
19	  const current: ColorScheme = resolvedTheme === "light" ? "light" : "dark";
20	  const target = nextTheme(current);
21	
22	  function toggle() {
23	    const apply = () => setTheme(target);
24	    const doc = document as Document & {
25	      startViewTransition?: (cb: () => void) => void;
26	    };
27	    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
28	    if (doc.startViewTransition && !reduced) {
29	      doc.startViewTransition(apply);
30	    } else {
31	      apply();
32	    }
33	  }
34	
35	  return (
36	    <button
37	      type="button"
38	      onClick={toggle}
39	      aria-label={mounted ? `Switch to ${target} theme` : "Switch theme"}
40	      className="grid size-7 place-items-center rounded-full text-dim transition-colors duration-150 hover:bg-surface hover:text-foreground"
41	    >
42	      {/* Both render until mounted so the control never shifts or flashes. */}
43	      <Sun className={`size-4 ${mounted && current === "dark" ? "block" : "hidden"}`} />
44	      <Moon className={`size-4 ${mounted && current === "dark" ? "hidden" : "block"}`} />
45	    </button>
46	  );
47	}
