244	   Masthead avatar slot — a designed absence (DESIGN.md §3). The footprint,
245	   the border, and the cursor-tracking light are all real; only the portrait
246	   is missing. Setting site.avatar swaps it in with no layout shift.
247	--------------------------------------------------------------------------- */
248	
249	.avatar-slot {
250	  position: relative;
251	  isolation: isolate;
252	  overflow: hidden;
253	  border-radius: 999px;
254	  border: 1px solid var(--border-strong);
255	  background: var(--surface);
256	}
257	
258	.avatar-slot::before {
259	  content: "";
260	  position: absolute;
261	  inset: -40%;
262	  z-index: 1;
263	  background: radial-gradient(
264	    42% 42% at var(--lx, 50%) var(--ly, 50%),
265	    var(--accent-quiet),
266	    transparent 70%
267	  );
268	  opacity: var(--lit, 0);
269	  transition: opacity 320ms var(--ease-out-quint);
270	}
271	
272	/* The grid of dots reads as "an image belongs here", not "an image failed". */
273	.avatar-slot::after {
274	  content: "";
275	  position: absolute;
276	  inset: 0;
277	  z-index: 2;
278	  background-image: radial-gradient(
279	    currentColor 0.5px,
280	    transparent 0.5px
281	  );
282	  background-size: 4px 4px;
283	  color: var(--dim);
284	  opacity: 0.42;
285	}
286	
287	/* ---------------------------------------------------------------------------
288	   Activity grid
289	--------------------------------------------------------------------------- */
290	
291	/* One column per week. Columns are the unit of layout, so narrow screens
292	   simply drop the oldest ones instead of shrinking every cell to a speck. */
293	.activity-grid {
294	  --cell-gap: 3px;
295	  display: grid;
296	  grid-template-columns: repeat(var(--weeks, 53), minmax(0, 1fr));
297	  gap: var(--cell-gap);
298	  width: 100%;
299	  outline: none;
300	}
301	
302	.activity-col {
303	  position: relative;
304	  display: grid;
305	  grid-template-rows: repeat(7, minmax(0, 1fr));
306	  gap: var(--cell-gap);
307	  padding-top: 1.05rem;
308	}
309	
310	/* Sits above its own column, allowed to overflow it. */
311	.activity-month {
312	  position: absolute;
313	  top: 0;
314	  left: 0;
315	  font-family: var(--font-mono);
316	  font-size: var(--text-2xs);
317	  line-height: 1;
318	  color: var(--dim);
319	  white-space: nowrap;
320	  pointer-events: none;
321	}
322	
323	.activity-cell {
324	  aspect-ratio: 1;
325	  border-radius: 2px;
326	  background: var(--level, var(--l0));
327	  position: relative;
328	  animation: cell-in 260ms var(--ease-out-quint) both;
329	  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
330	  transition:
331	    outline-color 120ms var(--ease-out-quint),
332	    background-color 150ms var(--ease-out-quint);
333	  outline: 1px solid transparent;
334	  outline-offset: 1.5px;
335	}
336	
337	.activity-cell[data-active="true"] {
338	  outline-color: var(--foreground);
339	}
340	
341	/* Today is a ring, never a fill — a projection must not read as a record. */
342	.activity-cell[data-live="true"]::after {
343	  content: "";
344	  position: absolute;
345	  inset: -2px;
346	  border-radius: 3px;
347	  border: 1px solid var(--accent);
348	}
349	
350	/* Half a year at a comfortable cell size beats a full year of dust. */
351	@media (max-width: 40rem) {
352	  .activity-grid {
353	    grid-template-columns: repeat(var(--weeks-sm, 27), minmax(0, 1fr));
354	  }
355	  .activity-col[data-narrow-hidden="true"] {
356	    display: none;
357	  }
358	}
359	
360	/* ---------------------------------------------------------------------------
361	   Rows
362	--------------------------------------------------------------------------- */
363	
364	.row-item {
365	  position: relative;
366	  display: block;
367	  padding: 1.125rem 0.75rem;
368	  margin-inline: -0.75rem;
369	  border-radius: 6px;
370	  transition: background-color 160ms var(--ease-out-quint);
371	}
372	.row-item:hover {
373	  background: color-mix(in oklab, var(--surface) 72%, transparent);
374	}
375	
376	.row-dest {
377	  opacity: 0;
378	  transform: translateY(2px);
379	  transition:
380	    opacity 160ms var(--ease-out-quint),
381	    transform 160ms var(--ease-out-quint);
382	}
383	.row-item:hover .row-dest,
384	.row-item:focus-visible .row-dest {
385	  opacity: 1;
386	  transform: none;
387	}
388	.row-item:hover .row-year,
389	.row-item:focus-visible .row-year {
390	  opacity: 0;
391	}
392	.row-year {
393	  transition: opacity 160ms var(--ease-out-quint);
394	}
395	
396	/* ---------------------------------------------------------------------------
397	   Prose (MDX)
398	--------------------------------------------------------------------------- */
399	
400	.prose {
401	  color: var(--foreground);
402	  font-size: var(--text-base);
403	}
404	.prose > * + * {
405	  margin-top: 1.35em;
406	}
407	.prose h2,
408	.prose h3 {
409	  font-family: var(--font-mono);
410	  font-size: var(--text-xs);
411	  font-weight: 500;
412	  letter-spacing: 0.09em;
413	  text-transform: uppercase;
414	  color: var(--dim);
415	  margin-top: 3rem;
416	  padding-top: 1.5rem;
417	  border-top: 1px solid var(--border);
418	}
419	.prose h2 + *,
420	.prose h3 + * {
421	  margin-top: 1rem;
422	}
423	.prose a {
424	  color: var(--foreground);
425	  text-decoration: underline;
426	  text-decoration-color: var(--border-strong);
427	  text-underline-offset: 3px;
428	  transition: text-decoration-color 150ms var(--ease-out-quint);
429	}
430	.prose a:hover {
431	  text-decoration-color: var(--accent);
432	}
433	.prose strong {
434	  font-weight: 550;
435	}
436	.prose ul,
437	.prose ol {
438	  padding-left: 1.25rem;
439	}
440	.prose ul {
441	  list-style: disc;
442	}
443	.prose ol {
444	  list-style: decimal;
445	}
446	.prose li::marker {
447	  color: var(--dim);
448	}
449	.prose li + li {
450	  margin-top: 0.5rem;
451	}
452	.prose blockquote {
453	  padding-left: 1.125rem;
454	  border-left: 1px solid var(--accent);
455	  color: var(--muted);
456	}
457	.prose hr {
458	  border: 0;
459	  border-top: 1px solid var(--border);
460	}
461	.prose img {
462	  border-radius: 8px;
463	  border: 1px solid var(--border);
464	}
465	.prose :not(pre) > code {
466	  font-family: var(--font-mono);
467	  font-size: 0.9em;
468	  background: var(--surface);
469	  border: 1px solid var(--border);
470	  border-radius: 4px;
471	  padding: 0.1em 0.35em;
472	}
473	.prose pre {
474	  font-family: var(--font-mono);
475	  font-size: var(--text-sm);
476	  background: var(--surface);
477	  border: 1px solid var(--border);
478	  border-radius: 8px;
479	  padding: 1rem 1.125rem;
480	  overflow-x: auto;
481	}
482	.prose pre code {
483	  background: none;
484	  border: 0;
485	  padding: 0;
486	}
487	.prose .anchor {
488	  position: absolute;
489	}
490	
491	/* sugar-high — four roles, no rainbow */
492	.prose pre .sh__token--keyword,
493	.prose pre .sh__token--sign {
494	  color: var(--accent);
495	}
496	.prose pre .sh__token--string,
497	.prose pre .sh__token--property {
498	  color: var(--muted);
499	}
500	.prose pre .sh__token--comment {
501	  color: var(--dim);
502	}
503	.prose pre .sh__token--identifier,
504	.prose pre .sh__token--entity {
505	  color: var(--foreground);
506	}
507	
508	/* ---------------------------------------------------------------------------
509	   Command palette
510	--------------------------------------------------------------------------- */
511	
512	@keyframes palette-in {
513	  from {
514	    opacity: 0;
515	    transform: translateY(8px) scale(0.985);
516	  }
517	  to {
518	    opacity: 1;
519	    transform: none;
520	  }
521	}
522	
523	.palette-panel {
524	  animation: palette-in 200ms var(--ease-out-quint) both;
525	}
526	
527	.palette-backdrop {
528	  animation: cell-in 160ms linear both;
529	  background: color-mix(in oklab, var(--background) 62%, transparent);
530	  backdrop-filter: blur(6px);
531	}
532	
533	/* ---------------------------------------------------------------------------
534	   Reduced motion: movement goes, colour feedback stays.
535	--------------------------------------------------------------------------- */
536	
537	@media (prefers-reduced-motion: reduce) {
538	  html {
539	    scroll-behavior: auto;
540	  }
541	  *,
542	  *::before,
543	  *::after {
544	    animation-duration: 0.001ms !important;
545	    animation-delay: 0ms !important;
546	    animation-iteration-count: 1 !important;
547	  }
548	  .reveal > *,
549	  .rule,
550	  .activity-cell,
551	  .palette-panel {
552	    animation: none !important;
553	    opacity: 1;
554	    transform: none;
555	  }
556	  .row-dest {
557	    transition: opacity 120ms linear;
558	  }
559	}
