input.content:
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/* ---------------------------------------------------------------------------
   Tokens. A neutral zinc system — no chromatic accent. Colour appears only
   where it carries meaning (links, status). `--line` is the hairline the
   whole frame is drawn with: the border colour, softened toward the
   background so a full-bleed rule reads as structure rather than a box.
--------------------------------------------------------------------------- */

:root {
  color-scheme: light;

  --background: oklch(1 0 0);
  --foreground: oklch(0.141 0.005 285.823); /* zinc-950 */

  --primary: oklch(0.141 0.005 285.823);
  --primary-foreground: oklch(0.985 0 0);

  --secondary: oklch(0.967 0.001 286.375); /* zinc-100 */
  --secondary-foreground: oklch(0.141 0.005 285.823);

  --muted: oklch(0.967 0.001 286.375); /* zinc-100 — a surface */
  --muted-foreground: oklch(0.552 0.016 285.938); /* zinc-500 */

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.141 0.005 285.823);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.141 0.005 285.823);

  --accent: oklch(0.967 0.001 286.375); /* zinc-100 */
  --accent-muted: color-mix(in oklab, var(--accent) 50%, transparent);
  --accent-foreground: oklch(0.21 0.006 285.885);

  --border: oklch(0.92 0.004 286.32); /* zinc-200 */
  --line: color-mix(in oklab, var(--border) 64%, var(--background));
  --input: oklch(0.92 0.004 286.32);
  --ring: oklch(0.705 0.015 286.067); /* zinc-400 */

  --info: oklch(0.67 0.17 244.98);
  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.577 0.245 27.325);
  --link: oklch(0.488 0.243 264.376); /* blue-700 */

  --surface: oklch(0.985 0 0);
  --surface-foreground: oklch(0.141 0.005 285.823);

  --code: var(--background);
  --code-foreground: var(--foreground);
  --code-number: oklch(0.24 0.01 0 / 0.3);
  --code-highlight: oklch(0.49 0.18 257.61 / 0.06);

  --selection: oklch(0.141 0.005 285.823);
  --selection-foreground: oklch(0.985 0 0);

  --header-height: --spacing(14);
  --fade-bottom-height: --spacing(24);
}

.dark {
  color-scheme: dark;

  --background: oklch(0.141 0.005 285.823);
  --foreground: oklch(0.985 0 0);

  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.141 0.005 285.823);

  --secondary: oklch(0.274 0.006 286.033); /* zinc-800 */
  --secondary-foreground: oklch(0.985 0 0);

  --muted: oklch(0.274 0.006 286.033);
  --muted-foreground: oklch(0.705 0.015 286.067); /* zinc-400 */

  --card: oklch(0.21 0.006 285.885); /* zinc-900 */
  --card-foreground: oklch(0.985 0 0);

  --popover: oklch(0.21 0.006 285.885);
  --popover-foreground: oklch(0.985 0 0);

  --accent: oklch(0.274 0.006 286.033);
  --accent-muted: color-mix(in oklab, var(--accent) 20%, transparent);
  --accent-foreground: oklch(0.985 0 0);

  --border: oklch(0.274 0.006 286.033);
  --input: lab(100% 0 0 / 0.15);
  --ring: oklch(0.552 0.016 285.938);

  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.505 0.213 27.518);
  --link: oklch(0.623 0.214 259.815); /* blue-500 */

  --surface: oklch(0.21 0.006 285.885);
  --surface-foreground: oklch(0.985 0 0);

  --code-number: oklch(0.43 0 0);
  --code-highlight: oklch(0.71 0.24 42.36 / 0.06);

  --selection: oklch(0.985 0 0);
  --selection-foreground: oklch(0.141 0.005 285.823);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);

  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);

  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-accent: var(--accent);
  --color-accent-muted: var(--accent-muted);
  --color-accent-foreground: var(--accent-foreground);

  --color-border: var(--border);
  --color-line: var(--line);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-info: var(--info);
  --color-success: var(--success);
  --color-destructive: var(--destructive);
  --color-link: var(--link);

  --color-surface: var(--surface);
  --color-surface-foreground: var(--surface-foreground);

  --color-code: var(--code);
  --color-code-foreground: var(--code-foreground);
  --color-code-number: var(--code-number);
  --color-code-highlight: var(--code-highlight);

  --color-selection: var(--selection);
  --color-selection-foreground: var(--selection-foreground);

  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace;
  --font-heading: var(--font-sans);
  --font-serif: var(--font-plex-serif), ui-serif, Georgia, serif;
  --font-handwriting: var(--font-caveat), var(--font-sans);

  --default-mono-font-feature-settings: "ss11" 1, "zero" 1, "tnum" 1;

  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);
}

/* ---------------------------------------------------------------------------
   Utilities. The frame system: hairlines that span the viewport rather than
   stopping at the content rail, and diagonal hatching for the gaps between
   panels.
--------------------------------------------------------------------------- */

@utility link {
  @apply decoration-1 underline-offset-3 hover:underline;
}

@utility link-underline {
  @apply underline decoration-current/30 decoration-1 underline-offset-3 transition-colors hover:decoration-current;
}

@utility screen-line-top {
  @apply relative;

  &:before {
    content: "";
    @apply absolute top-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-line-bottom {
  @apply relative;

  &:after {
    content: "";
    @apply absolute bottom-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-dashed-line-top {
  @apply screen-line-top;

  &:before {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-dashed-line-bottom {
  @apply screen-line-bottom;

  &:after {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-line-top-none {
  @apply before:content-none;
}

@utility screen-line-bottom-none {
  @apply after:content-none;
}

@utility diagonal-stripes {
  @apply [--pattern-foreground:var(--color-line)]/56;
  @apply bg-[repeating-linear-gradient(315deg,var(--pattern-foreground)_0,var(--pattern-foreground)_1px,transparent_0,transparent_50%)] bg-size-[10px_10px];
}

@utility stripe-divider {
  @apply relative h-8;

  &:before {
    content: "";
    @apply absolute left-[-100vw] -z-1 h-full w-[200vw] diagonal-stripes;
  }
}

/* Pointer-coarse devices get a 24px-minimum hit area without a 24px box. */
@utility extend-touch-target {
  @media (pointer: coarse) {
    @apply relative touch-manipulation after:absolute after:-inset-2;
  }
}

/* ---------------------------------------------------------------------------
   Base
--------------------------------------------------------------------------- */

@layer base {
  *,
  ::after,
  ::before,
  ::backdrop,
  ::file-selector-button {
    @apply border-border outline-ring/50;
  }

  html {
    -webkit-text-size-adjust: 100%;
    scroll-behavior: smooth;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-synthesis-weight: none;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    @apply bg-selection text-selection-foreground;
  }

  /* Suppress every transition until after first paint so the stored theme
     never animates in from the wrong colour. */
  .preload *,
  .preload *::before,
  .preload *::after {
    transition: none !important;
    animation: none !important;
  }

  ::-webkit-scrollbar {
    width: 5px;
    height: 5px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border);
    border-radius: 5px;
  }
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }

  [id] {
    @apply scroll-mt-18;
  }
}

/* ---------------------------------------------------------------------------
   Chrome
--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--background);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
  translate: -50% 0;
}

/* ---------------------------------------------------------------------------
   Typeset — the two long-form measures. `--typeset-flow` is the vertical
   rhythm between blocks, expressed in the block's own em so it scales with
   the measure rather than the root.
--------------------------------------------------------------------------- */

.typeset {
  --typeset-size: 1rem;
  --typeset-leading: 1.65;
  --typeset-flow: 1.25em;

  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  text-wrap: pretty;
}

.typeset > * + * {
  margin-top: var(--typeset-flow);
}

.typeset-description {
  --typeset-size: 15px;
  --typeset-leading: 1.6;
  --typeset-flow: 1em;
}

.typeset-timescale {
  --typeset-size: 0.875rem;
  --typeset-leading: 1.5;
  --typeset-flow: 1em;
}

/* ---------------------------------------------------------------------------
   Entrance. Rules draw, text settles. Nothing bounces, nothing loops.
--------------------------------------------------------------------------- */

@keyframes settle {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.reveal > * {
  animation: settle 380ms var(--ease-out-quint) both;
  animation-delay: calc(var(--i, 0) * 55ms + var(--base-delay, 0ms));
}

/* ---------------------------------------------------------------------------
   Activity mosaic. Fixed 12px blocks on a 2px gutter, square corners — the
   grid is a measuring instrument, so its cells are not decorated. Intensity
   is carried by the neutral foreground at five opacities.
--------------------------------------------------------------------------- */

.activity-grid {
  --cell-size: 12px;
  --cell-gap: 2px;
  display: grid;
  grid-template-columns: repeat(var(--weeks, 53), var(--cell-size));
  gap: var(--cell-gap);
  width: max-content;
  max-width: 100%;
  margin-inline: auto;
  outline: none;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, var(--cell-size));
  gap: var(--cell-gap);
  padding-top: 1.05rem;
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  pointer-events: none;
}

.activity-cell {
  background: color-mix(
    in oklab,
    var(--muted-foreground) var(--level, 10%),
    transparent
  );
  position: relative;
  animation: fade-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
  transition:
    outline-color 120ms var(--ease-out-quint),
    background-color 150ms var(--ease-out-quint);
  outline: 1px solid transparent;
  outline-offset: 1px;
}

.activity-cell[data-active="true"] {
  outline-color: var(--foreground);
}

/* Today is a ring, never a fill — a projection must not read as a record. */
.activity-cell[data-live="true"]::after {
  content: "";
  position: absolute;
  inset: -2px;
  border: 1px solid var(--muted-foreground);
}

/* Half a year at full cell size beats a full year of dust. */
@media (max-width: 40rem) {
  .activity-grid {
    grid-template-columns: repeat(var(--weeks-sm, 27), var(--cell-size));
  }
  .activity-col[data-narrow-hidden="true"] {
    display: none;
  }
}

/* ---------------------------------------------------------------------------
   Prose (MDX) — long-form runs on the serif; structure stays sans.
--------------------------------------------------------------------------- */

.prose {
  font-family: var(--font-serif);
  color: var(--foreground);
}
.prose h2,
.prose h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  letter-spacing: -0.01em;
  scroll-margin-top: calc(var(--header-height) + 1rem);
}
.prose h2 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
}
.prose a {
  color: var(--link);
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 150ms var(--ease-out-quint);
}
.prose a:hover {
  text-decoration-color: currentColor;
}
.prose strong {
  font-weight: 600;
}
.prose ul,
.prose ol {
  padding-left: 1.25rem;
}
.prose ul {
  list-style: disc;
}
.prose ol {
  list-style: decimal;
}
.prose li::marker {
  color: var(--muted-foreground);
}
.prose li + li {
  margin-top: 0.5rem;
}
.prose blockquote {
  padding-left: 1.125rem;
  border-left: 2px solid var(--border);
  color: var(--muted-foreground);
  font-style: italic;
}
.prose hr {
  border: 0;
  border-top: 1px solid var(--line);
}
.prose img {
  border: 1px solid var(--line);
}
.prose :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: var(--muted);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
.prose pre {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  background: var(--code);
  color: var(--code-foreground);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1rem 1.125rem;
  overflow-x: auto;
}
.prose pre code {
  background: none;
  border: 0;
  padding: 0;
}
.prose .anchor {
  position: absolute;
}

/* sugar-high — four roles, no rainbow */
.prose pre .sh__token--keyword,
.prose pre .sh__token--sign {
  color: var(--link);
}
.prose pre .sh__token--string,
.prose pre .sh__token--property {
  color: var(--muted-foreground);
}
.prose pre .sh__token--comment {
  color: var(--code-number);
}
.prose pre .sh__token--identifier,
.prose pre .sh__token--entity {
  color: var(--foreground);
}

/* ---------------------------------------------------------------------------
   Command palette
--------------------------------------------------------------------------- */

@keyframes palette-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.palette-panel {
  animation: palette-in 200ms var(--ease-out-quint) both;
}

.palette-backdrop {
  animation: fade-in 160ms linear both;
  background: color-mix(in oklab, var(--background) 62%, transparent);
  backdrop-filter: blur(6px);
}

/* ---------------------------------------------------------------------------
   Reduced motion: movement goes, colour feedback stays.
--------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
  }
  .reveal > *,
  .activity-cell,
  .palette-panel {
    animation: none !important;
    opacity: 1;
    transform: none;
  }
}

import { cn } from "@/lib/utils";

/**
 * The page is a stack of panels sharing one vertical rail. A panel draws its
 * own left/right edges and a full-bleed hairline top and bottom, so the frame
 * continues past the content column to the edge of the viewport. Everything
 * on the site is composed from these six parts — there is no other container.
 */
export function Panel({ className, ...props }: React.ComponentProps<"section">) {
  return (
    <section
      data-slot="panel"
      className={cn(
        "screen-line-top screen-line-bottom border-x border-line",
        className,
      )}
      {...props}
    />
  );
}

export function PanelHeader({
  className,
  ...props
}: React.ComponentProps<"header">) {
  return (
    <header
      data-slot="panel-header"
      className={cn(
        "screen-line-bottom px-4 has-data-[slot=panel-description]:*:data-[slot=panel-title]:screen-line-bottom",
        className,
      )}
      {...props}
    />
  );
}

export function PanelTitle({ className, ...props }: React.ComponentProps<"h2">) {
  return (
    <h2
      data-slot="panel-title"
      className={cn(
        "group/panel-title font-heading text-3xl font-medium tracking-tight text-balance",
        className,
      )}
      {...props}
    />
  );
}

/** The count or unit that rides above the baseline of a title. */
export function PanelTitleSup({
  className,
  ...props
}: React.ComponentProps<"sup">) {
  return (
    <sup
      className={cn(
        "top-[-0.75em] ml-1 text-sm font-medium tracking-normal text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

export function PanelDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="panel-description"
      className={cn(
        "py-4 text-base text-balance text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

export function PanelContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div data-slot="panel-body" className={cn("p-4", className)} {...props} />
  );
}

import { cn } from "@/lib/utils";

/**
 * A 24px recessed square that holds one 16px glyph. Used as the left gutter
 * marker on list rows, where it gives every row the same optical origin
 * regardless of how long its title runs.
 */
export function IconTile({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="icon-tile"
      className={cn(
        "flex size-6 shrink-0 items-center justify-center rounded-md select-none",
        "border border-muted-foreground/15 bg-muted text-muted-foreground",
        "ring-1 ring-border/50 ring-offset-1 ring-offset-background dark:ring-line",
        "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      {...props}
    />
  );
}

import { cn } from "@/lib/utils";

/** A fact, not a badge: monospace, no fill of its own beyond one zinc step. */
export function Tag({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="tag"
      className={cn(
        "inline-flex items-center rounded-full border bg-zinc-50 px-1.5 py-0.5 font-mono text-xs text-muted-foreground dark:bg-zinc-900",
        "[&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5",
        className,
      )}
      {...props}
    />
  );
}

import { cn } from "@/lib/utils";

/**
 * A hairline. Horizontal by default; the vertical form is used inside the
 * header and footer to space icon groups.
 */
export function Separator({
  className,
  orientation = "horizontal",
  ...props
}: React.ComponentProps<"div"> & {
  orientation?: "horizontal" | "vertical";
}) {
  return (
    <div
      data-slot="separator"
      data-orientation={orientation}
      role="none"
      className={cn(
        "shrink-0 bg-border",
        orientation === "horizontal" ? "h-px w-full" : "h-full w-px",
        className,
      )}
      {...props}
    />
  );
}

