export type ColorScheme = "light" | "dark";
/** What the Visitor has asked for — including "ask my OS". */
export type ThemePreference = ColorScheme | "system";

/**
 * The site follows the operating system until the Visitor says otherwise. A
 * manual choice always wins and is persisted. Runtime applies this via
 * `next-themes`; this module is the contract.
 */
export const DEFAULT_THEME: ThemePreference = "system";

/** Used only where the OS expresses no preference at all. */
export const FALLBACK_SCHEME: ColorScheme = "dark";

export function resolveTheme(
  preference: ThemePreference | null,
  systemScheme: ColorScheme | null = null,
): ColorScheme {
  if (preference === "light" || preference === "dark") return preference;
  return systemScheme ?? FALLBACK_SCHEME;
}

export function nextTheme(current: ColorScheme): ColorScheme {
  return current === "dark" ? "light" : "dark";
}

import { expect, test } from "bun:test";
import {
  DEFAULT_THEME,
  FALLBACK_SCHEME,
  nextTheme,
  resolveTheme,
} from "@/lib/theme";

test("the OS is followed when nothing is stored", () => {
  expect(DEFAULT_THEME).toBe("system");
  expect(resolveTheme(null, "light")).toBe("light");
  expect(resolveTheme("system", "light")).toBe("light");
  expect(resolveTheme("system", "dark")).toBe("dark");
});

test("a silent OS falls back to the primary design", () => {
  expect(resolveTheme(null)).toBe(FALLBACK_SCHEME);
  expect(resolveTheme("system", null)).toBe("dark");
});

test("a manual override always wins", () => {
  expect(resolveTheme("light", "dark")).toBe("light");
  expect(resolveTheme("dark", "light")).toBe("dark");
});

test("toggling alternates between exactly two schemes", () => {
  expect(nextTheme("dark")).toBe("light");
  expect(nextTheme("light")).toBe("dark");
  expect(nextTheme(nextTheme("dark"))).toBe("dark");
});

"use client";

import { ThemeProvider as NextThemeProvider } from "next-themes";
import { DEFAULT_THEME, FALLBACK_SCHEME } from "@/lib/theme";

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  return (
    <NextThemeProvider
      attribute="class"
      defaultTheme={DEFAULT_THEME}
      enableSystem
      // Applied when the OS reports no preference at all.
      fallback={FALLBACK_SCHEME}
      disableTransitionOnChange={false}
      storageKey="theme"
    >
      {children}
    </NextThemeProvider>
  );
}

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import { Moon, Sun } from "@/components/icons";
import { nextTheme, type ColorScheme } from "@/lib/theme";

/** Never fires — the snapshot difference alone reports "hydrated". */
const noSubscribe = () => () => {};

export function ThemeToggle() {
  const { resolvedTheme, setTheme } = useTheme();
  const mounted = useSyncExternalStore(
    noSubscribe,
    () => true,
    () => false,
  );

  const current: ColorScheme = resolvedTheme === "light" ? "light" : "dark";
  const target = nextTheme(current);

  function toggle() {
    const apply = () => setTheme(target);
    const doc = document as Document & {
      startViewTransition?: (cb: () => void) => void;
    };
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (doc.startViewTransition && !reduced) {
      doc.startViewTransition(apply);
    } else {
      apply();
    }
  }

  return (
    <button
      type="button"
      onClick={toggle}
      aria-label={mounted ? `Switch to ${target} theme` : "Switch theme"}
      className="flex size-8 touch-manipulation items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground"
    >
      {/* Both render until mounted so the control never shifts or flashes. */}
      <Sun className={`size-4.5 ${mounted && current === "dark" ? "block" : "hidden"}`} />
      <Moon className={`size-4.5 ${mounted && current === "dark" ? "hidden" : "block"}`} />
    </button>
  );
}

