"use client";

import { useId, useMemo, useState } from "react";
import type { CSSProperties } from "react";
import { formatTokenCount } from "@/lib/ai-activity";
import type { ActivityDay } from "@/lib/ai-activity";
import { formatActivityDate, type ActivityWeek } from "@/lib/activity-grid";

const MOBILE_WEEKS = 27;

/** Five steps of the neutral foreground. Intensity is opacity, never hue. */
export const LEVEL_ALPHA = ["10%", "20%", "40%", "60%", "80%"] as const;

function cellLabel(day: ActivityDay): string {
  const tokens = `${formatTokenCount(day.tokens)} tokens`;
  return day.live
    ? `${formatActivityDate(day.date)}: ${tokens} so far today`
    : `${formatActivityDate(day.date)}: ${tokens}`;
}

/**
 * A single tab stop with arrow-key traversal (listbox pattern), so 365 cells
 * never become 365 tab stops. The readout is aria-hidden — the focused
 * option already carries the same sentence.
 */
export function ActivityGrid({ weeks }: { weeks: readonly ActivityWeek[] }) {
  const gridId = useId();
  const slots = useMemo(() => weeks.flatMap((week) => week.cells), [weeks]);
  const lastFilled = useMemo(
    () => slots.reduce((last, slot, i) => (slot ? i : last), 0),
    [slots],
  );
  const [active, setActive] = useState<number | null>(null);

  function move(delta: number) {
    setActive((current) => {
      const next = (current ?? lastFilled) + delta;
      if (next < 0 || next >= slots.length || !slots[next]) return current;
      return next;
    });
  }

  const activeDay = active === null ? null : slots[active];

  return (
    <div className="overflow-x-auto">
      <p
        aria-hidden
        className="mb-2.5 h-4 px-4 font-mono text-xs text-muted-foreground tabular-nums"
      >
        {activeDay ? (
          <>
            <span className="text-foreground">
              {formatTokenCount(activeDay.tokens)}
            </span>{" "}
            tokens · {formatActivityDate(activeDay.date)}
            {activeDay.live ? " · so far today" : ""}
          </>
        ) : (
          "hover or focus a day"
        )}
      </p>

      <div
        role="listbox"
        tabIndex={0}
        aria-label="Daily AI token usage, last 12 months"
        aria-activedescendant={
          active !== null && slots[active] ? `${gridId}-${active}` : undefined
        }
        className="activity-grid"
        style={
          {
            "--weeks": weeks.length,
            "--weeks-sm": MOBILE_WEEKS,
          } as CSSProperties
        }
        onFocus={() => setActive((current) => current ?? lastFilled)}
        onBlur={() => setActive(null)}
        onMouseLeave={() => setActive(null)}
        onKeyDown={(event) => {
          const step =
            event.key === "ArrowLeft"
              ? -7
              : event.key === "ArrowRight"
                ? 7
                : event.key === "ArrowUp"
                  ? -1
                  : event.key === "ArrowDown"
                    ? 1
                    : 0;
          if (step === 0) return;
          event.preventDefault();
          move(step);
        }}
      >
        {weeks.map((week, weekIndex) => (
          <div
            key={week.key}
            className="activity-col"
            // Derived, not a fixed nth-child: a 365-day window is 53 or 54
            // columns, and the narrow grid must show exactly MOBILE_WEEKS.
            data-narrow-hidden={
              weekIndex < weeks.length - MOBILE_WEEKS ? "true" : undefined
            }
          >
            {week.monthLabel ? (
              <span className="activity-month">{week.monthLabel}</span>
            ) : null}
            {week.cells.map((day, dayIndex) => {
              const index = weekIndex * 7 + dayIndex;
              if (!day) {
                return <div key={index} aria-hidden />;
              }
              return (
                <div
                  key={index}
                  id={`${gridId}-${index}`}
                  role="option"
                  aria-selected={index === active}
                  aria-label={cellLabel(day)}
                  data-active={index === active}
                  data-live={day.live ? "true" : undefined}
                  onMouseEnter={() => setActive(index)}
                  className="activity-cell"
                  style={
                    {
                      "--level": LEVEL_ALPHA[day.intensity],
                      "--col": weekIndex,
                    } as CSSProperties
                  }
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

import { ActivityGrid, LEVEL_ALPHA } from "@/components/activity-grid";
import {
  Panel,
  PanelDescription,
  PanelHeader,
  PanelTitle,
  PanelTitleSup,
} from "@/components/panel";
import { Tag } from "@/components/tag";
import { buildActivityWeeks } from "@/lib/activity-grid";
import { formatTokenCount, materializeAiActivity } from "@/lib/ai-activity";
import { getAiActivityPayload } from "@/lib/ai-activity-store";

function updatedLabel(generatedAt: string | null, timeZone: string): string {
  if (!generatedAt) return "";
  const date = new Date(generatedAt);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    timeZone,
  }).format(date);
}

export async function ActivitySection() {
  const { payload, source } = await getAiActivityPayload();
  const activity = materializeAiActivity(payload);
  const weeks = buildActivityWeeks(activity.days);
  const updated = updatedLabel(activity.generatedAt, activity.timezone);
  // Only a feed published through yesterday earns a projected today.
  const projecting = activity.days.at(-1)?.live === true;

  const provenance =
    source === "fallback"
      ? "fixture data — the live feed is unavailable"
      : !updated
        ? ""
        : projecting
          ? `updated ${updated}`
          : `feed stalled — last updated ${updated}`;

  return (
    <Panel id="activity">
      <PanelHeader>
        <PanelTitle>
          AI activity
          <PanelTitleSup>{formatTokenCount(activity.lifetimeTokens)}</PanelTitleSup>
        </PanelTitle>
        <PanelDescription>
          Tokens through coding agents since I started measuring — one cell per
          day
          {projecting
            ? ", today ringed rather than filled because it is still a projection."
            : "."}
        </PanelDescription>
      </PanelHeader>

      <div className="py-4">
        <ActivityGrid weeks={weeks} />
      </div>

      <figcaption className="flex items-center justify-between gap-4 border-t border-line px-4 py-3 text-sm text-muted-foreground">
        <span className="flex items-center gap-2">
          <span className="tracking-wide text-muted-foreground/80">Fig. 2.</span>
          {source === "fallback" ? <Tag>fixture</Tag> : null}
          <span>{provenance}</span>
        </span>
        <span className="flex shrink-0 items-center gap-1 font-mono text-xs">
          less
          {LEVEL_ALPHA.map((alpha) => (
            <span
              key={alpha}
              aria-hidden
              className="size-2.5"
              style={{
                background: `color-mix(in oklab, var(--muted-foreground) ${alpha}, transparent)`,
              }}
            />
          ))}
          more
        </span>
      </figcaption>
    </Panel>
  );
}

