44	function textFromChildren(children: React.ReactNode): string {
45	  return React.Children.toArray(children)
46	    .map((child) => {
47	      if (typeof child === "string" || typeof child === "number") {
48	        return String(child);
49	      }
50	      if (React.isValidElement<{ children?: React.ReactNode }>(child)) {
51	        return textFromChildren(child.props.children);
