/** The lattice spans -2..3 on both axes, symmetric about the figure's centre. */
const FLOOR_LO = -2;
const FLOOR_HI = 3;

/**
 * The floor the figure stands on: the same two isometric axes as the cubes,
 * ruled rather than filled. It runs off every edge of the plate and is clipped
 * there, which is the frame's own habit — lines are cut by the viewport, never
 * tidied to fit. Without it the mark floats in void; with it the plate reads as
 * a drawing sheet.
 */
function FloorPlane() {
  const lines: Array<[[number, number], [number, number], number]> = [];
  for (let i = FLOOR_LO; i <= FLOOR_HI; i += 1) {
    // Fade with distance from the figure's centre (0.5) so the clipped ends
    // are already faint by the time they reach the edge.
    const fade = 1 - Math.abs(i - 0.5) / (FLOOR_HI - FLOOR_LO);
    lines.push([ground(FLOOR_LO, i), ground(FLOOR_HI, i), fade]);
    lines.push([ground(i, FLOOR_LO), ground(i, FLOOR_HI), fade]);
