  return (
    <g stroke="currentColor" strokeWidth={0.5}>
      {lines.map(([[x1, y1], [x2, y2], fade], i) => (
        <line
          key={i}
          x1={round(x1)}
          y1={round(y1)}
          x2={round(x2)}
          y2={round(y2)}
          strokeOpacity={round(0.22 * fade)}
