              className="max-w-screen flex-1 overflow-x-clip px-2 outline-none"
            >
              <div className="mx-auto md:max-w-3xl">{children}</div>
            </main>
            <SiteFooter />
          </div>
        </ThemeProvider>
        <Analytics />
        <SpeedInsights />
      </body>
    </html>
  );
}

