cat > lib/glyph-404.ts <<'EOF'
/**
 * Numerals drawn on a 5×7 bitmap — the smallest grid a legible digit fits in,
 * and the same square the activity grid spends a day on. Only the two digits
 * `404` needs exist here; anything else is a typo, not a feature.
 */
const DIGITS: Record<string, readonly string[]> = {
  "0": ["01110", "10001", "10011", "10101", "11001", "10001", "01110"],
  "4": ["00010", "00110", "01010", "10010", "11111", "00010", "00010"],
};

export const GLYPH_ROWS = 7;
const GLYPH_WIDTH = 5;

export type GlyphField = {
  cols: number;
  rows: number;
  /** Row-major, `cols * rows` long. `true` is a lit cell. */
  cells: boolean[];
};

/**
 * Lay digits out left to right with one blank column between them, and return
 * the whole plate row-major so a single `map` can draw it.
 */
export function glyphField(text: string): GlyphField {
  const glyphs = [...text].map((char) => {
    const bitmap = DIGITS[char];
    if (!bitmap) throw new Error(`No bitmap for "${char}"`);
    return bitmap;
  });

  // One separating column between neighbours, none on the outside.
  const cols = glyphs.length * GLYPH_WIDTH + Math.max(glyphs.length - 1, 0);
  const cells: boolean[] = [];

  for (let row = 0; row < GLYPH_ROWS; row += 1) {
    glyphs.forEach((bitmap, index) => {
      if (index > 0) cells.push(false);
      for (const bit of bitmap[row]!) cells.push(bit === "1");
    });
  }

  return { cols, rows: GLYPH_ROWS, cells };
}
EOF
cat > lib/glyph-404.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { glyphField, GLYPH_ROWS } from "@/lib/glyph-404";

test("404 is three 5-wide digits with a blank column between them", () => {
  const field = glyphField("404");
  expect(field.cols).toBe(17);
  expect(field.rows).toBe(GLYPH_ROWS);
  expect(field.cells).toHaveLength(17 * GLYPH_ROWS);
  // The separator columns are index 5 and 11 of every row, and never lit.
  for (let row = 0; row < GLYPH_ROWS; row += 1) {
    expect(field.cells[row * 17 + 5]).toBe(false);
    expect(field.cells[row * 17 + 11]).toBe(false);
  }
});

test("the crossbar row of a 4 is solid and the bowl of a 0 is open", () => {
  const { cells } = glyphField("404");
  const row = (r: number) => cells.slice(r * 17, r * 17 + 17);
  // Row 4 is the 4's crossbar: five lit cells under the first digit.
  expect(row(4).slice(0, 5)).toEqual([true, true, true, true, true]);
