 * reaches it, before first paint and long before the bundle, and React takes
 * over the tick from there. The three values are marked
 * `suppressHydrationWarning` because they are *expected* to differ from what
 * the server wrote — that difference is the whole point.
 */
export function LocalTime({ zone }: { zone: string }) {
  const uid = useId();
  const timeId = `lt-time-${uid}`;
  const diffId = `lt-diff-${uid}`;
  const handsId = `lt-hands-${uid}`;

  useEffect(() => {
    function paint() {
      const now = new Date();
      const { hour, minute } = zoneClock(zone, now);
      // `getTimezoneOffset` is minutes *behind* UTC, so adding it to the
      // author's offset gives the signed distance from the reader.
      const away = zoneOffsetMinutes(zone, now) + now.getTimezoneOffset();
      const time = document.getElementById(timeId);
      if (time) time.textContent = formatZoneTime(zone, now);
      const diff = document.getElementById(diffId);
      if (diff) diff.textContent = ` // ${offsetLabel(away)}`;
      document
        .getElementById(handsId)
        ?.setAttribute("d", handsPath(hour, minute));
    }
    paint();
    // A clock showing only minutes still has to turn over on the minute, and
    // there is no telling where inside one this mounted.
    const timer = window.setInterval(paint, 5_000);
    return () => window.clearInterval(timer);
  }, [zone, timeId, diffId, handsId]);

  const now = new Date();
  const { hour, minute } = zoneClock(zone, now);

  return (
    <OverviewRow icon={<ClockIcon hands={handsPath(hour, minute)} handsId={handsId} />}>
      <span id={timeId} suppressHydrationWarning>
        {formatZoneTime(zone, now)}
