var mt=M/60*T,ht=(H%12+M/60)/12*T;
var e=document.getElementById(i[0]);if(e)e.textContent=new Intl.DateTimeFormat("en-US",{timeZone:z,hour:"2-digit",minute:"2-digit",hour12:true}).format(n);
var c=document.getElementById(i[1]);if(c)c.textContent=" // "+d;
