 13 │ function cellLabel(day: ActivityDay): string {
 14 │   const date = formatActivityDate(day.date);
 15 │   // An unreported day has no number to read out. Saying "0 tokens" here would
 16 │   // put the same lie in the screen reader that a filled cell puts on screen.
 17 │   if (day.recorded === false) return `${date}: no data`;
 18 │   const tokens = `${formatTokenCount(day.tokens)} tokens`;
 19 │   return day.live ? `${date}: ${tokens} so far today` : `${date}: ${tokens}`;
 20 │ }
