 22 │ /**
 23 │  * A single tab stop with arrow-key traversal (listbox pattern), so 365 cells
 24 │  * never become 365 tab stops. The readout is aria-hidden — the focused
 25 │  * option already carries the same sentence.
 26 │  */
 27 │ export function ActivityGrid({ weeks }: { weeks: readonly ActivityWeek[] }) {
 28 │   const gridId = useId();
 29 │   const slots = useMemo(() => weeks.flatMap((week) => week.cells), [weeks]);
 30 │   const lastFilled = useMemo(
 31 │     () => slots.reduce((last, slot, i) => (slot ? i : last), 0),
 32 │     [slots],
 33 │   );
 34 │   const [active, setActive] = useState<number | null>(null);
 35 │   const scrollRef = useRef<HTMLDivElement>(null);
 36 │ 
 37 │   // When the year is genuinely wider than the rail, the end of it is the part
 38 │   // worth opening on: the caption talks about today, and today is the last
 39 │   // column. A rail that is short by only a few pixels is left where it is —
 40 │   // scrolling it would push the first week under the edge fade for nothing.
 41 │   useEffect(() => {
 42 │     const strip = scrollRef.current;
 43 │     if (!strip) return;
 44 │     const overflow = strip.scrollWidth - strip.clientWidth;
 45 │     if (overflow > 64) strip.scrollLeft = strip.scrollWidth;
 46 │   }, [weeks]);
 47 │ 
 48 │   function move(delta: number) {
 49 │     setActive((current) => {
 50 │       const next = (current ?? lastFilled) + delta;
 51 │       if (next < 0 || next >= slots.length || !slots[next]) return current;
 52 │       return next;
 53 │     });
 54 │   }
 55 │ 
 56 │   const activeDay = active === null ? null : slots[active];
 57 │ 
 58 │   return (
 59 │     <div>
 60 │       <p
 61 │         aria-hidden
 62 │         className="mb-2.5 h-4 px-4 font-mono text-xs text-muted-foreground tabular-nums"
 63 │       >
 64 │         {activeDay ? (
 65 │           activeDay.recorded === false ? (
 66 │             <>
 67 │               <span className="text-foreground">no data</span> ·{" "}
 68 │               {formatActivityDate(activeDay.date)}
 69 │             </>
 70 │           ) : (
 71 │             <>
 72 │               <span className="text-foreground">
 73 │                 {formatTokenCount(activeDay.tokens)}
 74 │               </span>{" "}
 75 │               tokens · {formatActivityDate(activeDay.date)}
 76 │               {activeDay.live ? " · so far today" : ""}
 77 │             </>
 78 │           )
 79 │         ) : (
 80 │           "hover or focus a day"
 81 │         )}
 82 │       </p>
 83 │ 
 84 │       {/* The full year always renders; on a narrow viewport it is reached by
 85 │           dragging the strip sideways rather than by dropping half of it. A
 86 │           year with six months cut out of it is not the measurement the
 87 │           caption claims. */}
 88 │       <div ref={scrollRef} className="activity-scroll">
 89 │         <div
 90 │           role="listbox"
 91 │           tabIndex={0}
 92 │           aria-label="Daily AI token usage, last 12 months"
 93 │           aria-activedescendant={
 94 │             active !== null && slots[active] ? `${gridId}-${active}` : undefined
 95 │           }
 96 │           className="activity-grid"
 97 │           style={{ "--weeks": weeks.length } as CSSProperties}
 98 │           onFocus={() => setActive((current) => current ?? lastFilled)}
 99 │           onBlur={() => setActive(null)}
100 │           onMouseLeave={() => setActive(null)}
101 │           onKeyDown={(event) => {
102 │             const step =
103 │               event.key === "ArrowLeft"
104 │                 ? -7
105 │                 : event.key === "ArrowRight"
106 │                   ? 7
107 │                   : event.key === "ArrowUp"
108 │                     ? -1
109 │                     : event.key === "ArrowDown"
