117 │           {weeks.map((week, weekIndex) => (
118 │             <div key={week.key} className="activity-col">
119 │               {week.monthLabel ? (
120 │                 <span className="activity-month">{week.monthLabel}</span>
121 │               ) : null}
122 │               {week.cells.map((day, dayIndex) => {
123 │                 const index = weekIndex * 7 + dayIndex;
124 │                 if (!day) {
125 │                   return <div key={index} aria-hidden />;
