134 │                     data-active={index === active}
135 │                     data-live={day.live ? "true" : undefined}
136 │                     data-recorded={day.recorded === false ? "false" : undefined}
137 │                     onMouseEnter={() => setActive(index)}
138 │                     className="activity-cell"
139 │                     style={
140 │                       {
141 │                         "--level": LEVEL_ALPHA[day.intensity] ?? LEVEL_ALPHA[0],
142 │                         "--col": weekIndex,
143 │                       } as CSSProperties
144 │                     }
145 │                   />
146 │                 );
147 │               })}
148 │             </div>
149 │           ))}
150 │         </div>
151 │       </div>
152 │     </div>
