  8 │ export type DailyTokens = {
  9 │   date: string;
 10 │   tokens: number;
 11 │   /**
 12 │    * Present, and `false`, only for days the feed never reached. A day measured
 13 │    * at zero and a day never measured are both "no tokens", but only the first
 14 │    * is a fact — the grid must not draw them the same. Absent means recorded,
 15 │    * so a series that is fully covered serialises exactly as it always did.
 16 │    */
 17 │   recorded?: false;
 18 │ };
 19 │ 
 20 │ export type Intensity = 0 | 1 | 2 | 3 | 4;
 21 │ 
 22 │ export type ActivityDay = DailyTokens & {
 23 │   intensity: Intensity;
 24 │   /** Synthetic “live” projection for the current local day. */
 25 │   live?: boolean;
 26 │ };
 27 │ 
 28 │ export type AiActivity = {
 29 │   days: ActivityDay[];
 30 │   lifetimeTokens: number;
 31 │   /** ISO timestamp of the nightly payload, when known. */
 32 │   generatedAt: string | null;
 33 │   timezone: string;
 34 │ };
 35 │ 
 36 │ export type AiActivitySource = "blob" | "fallback";
 37 │ 
 38 │ /** GitHub-like 5-level scale relative to the densest day in the series. */
 39 │ export function intensityFromTokens(
 40 │   tokens: number,
 41 │   maxTokens: number,
 42 │ ): Intensity {
 43 │   if (tokens <= 0 || maxTokens <= 0) return 0;
 44 │   const ratio = tokens / maxTokens;
 45 │   if (ratio <= 0.25) return 1;
 46 │   if (ratio <= 0.5) return 2;
 47 │   if (ratio <= 0.75) return 3;
 48 │   return 4;
 49 │ }
 50 │ 
 51 │ /**
 52 │  * Expand a sparse daily series into consecutive calendar days (0-filled gaps)
 53 │  * ending on `endDate`, keeping at most `windowDays` cells.
 54 │  *
 55 │  * Gaps *inside* the feed's coverage are real zeroes — the feed ran that day and
 56 │  * reported nothing. Days outside it are not, at either end: a day before the
 57 │  * first report is a day nobody was counting, exactly as a day after the last
 58 │  * one is. Both are marked unrecorded so the grid can draw the difference
 59 │  * instead of back-dating a year of quiet days the meter never saw.
 60 │  */
 61 │ export function fillSparseDailySeries(
 62 │   days: readonly DailyTokens[],
 63 │   endDate: string,
 64 │   windowDays = 365,
 65 │ ): DailyTokens[] {
 66 │   const byDate = new Map(days.map((d) => [d.date, d.tokens]));
 67 │   const covered = days.reduce((last, d) => (d.date > last ? d.date : last), "");
 68 │   const began = days.reduce(
 69 │     (first, d) => (!first || d.date < first ? d.date : first),
 70 │     "",
 71 │   );
 72 │   const startDate = shiftYmd(endDate, -(windowDays - 1));
 73 │   const filled: DailyTokens[] = [];
 74 │   for (
 75 │     let cursor = startDate;
 76 │     cursor <= endDate;
 77 │     cursor = shiftYmd(cursor, 1)
 78 │   ) {
 79 │     filled.push(
 80 │       began && cursor >= began && cursor <= covered
 81 │         ? { date: cursor, tokens: byDate.get(cursor) ?? 0 }
 82 │         : { date: cursor, tokens: 0, recorded: false },
 83 │     );
 84 │   }
 85 │   return filled;
 86 │ }
 87 │ 
 88 │ export function buildAiActivity(
 89 │   series: readonly DailyTokens[],
 90 │   options?: {
 91 │     liveDate?: string;
 92 │     generatedAt?: string | null;
 93 │     timezone?: string;
 94 │     /** Authoritative lifetime from the payload (preferred over series sum). */
 95 │     lifetimeTokens?: number;
 96 │   },
 97 │ ): AiActivity {
 98 │   const max = Math.max(0, ...series.map((d) => d.tokens));
 99 │   const liveDate = options?.liveDate;
100 │ 
101 │   const days: ActivityDay[] = series.map((day) => ({
102 │     ...day,
103 │     intensity: intensityFromTokens(day.tokens, max),
104 │     live: liveDate === day.date ? true : undefined,
105 │   }));
106 │ 
107 │   const seriesSum = series.reduce((sum, day) => sum + day.tokens, 0);
108 │   const lifetimeTokens =
109 │     options?.lifetimeTokens !== undefined
110 │       ? options.lifetimeTokens
111 │       : seriesSum;
112 │ 
113 │   return {
114 │     days,
115 │     lifetimeTokens,
116 │     generatedAt: options?.generatedAt ?? null,
117 │     timezone: options?.timezone ?? AI_ACTIVITY_TIMEZONE,
118 │   };
119 │ }
120 │ 
121 │ /**
122 │  * Fraction of the local calendar day elapsed [0, 1].
123 │  */
124 │ export function dayFractionElapsed(now: Date, timeZone: string): number {
125 │   const parts = new Intl.DateTimeFormat("en-US", {
126 │     timeZone,
127 │     hour: "numeric",
128 │     minute: "numeric",
129 │     second: "numeric",
130 │     hourCycle: "h23",
131 │   }).formatToParts(now);
132 │   const hour = Number(parts.find((p) => p.type === "hour")?.value ?? 0);
133 │   const minute = Number(parts.find((p) => p.type === "minute")?.value ?? 0);
134 │   const second = Number(parts.find((p) => p.type === "second")?.value ?? 0);
135 │   const elapsed = hour * 3600 + minute * 60 + second;
136 │   return Math.min(1, Math.max(0, elapsed / 86_400));
137 │ }
138 │ 
139 │ /**
140 │  * Conservative full-day baseline: minimum of the last up-to-7 days
141 │  * before `beforeDate` that have tokens > 0.
142 │  */
143 │ export function sevenDayMinBaseline(
144 │   days: readonly { date: string; tokens: number }[],
145 │   beforeDate: string,
146 │ ): number {
147 │   const prior = days
148 │     .filter((d) => d.date < beforeDate && d.tokens > 0)
149 │     .sort((a, b) => a.date.localeCompare(b.date))
150 │     .slice(-7);
151 │   if (prior.length === 0) return 0;
152 │   return Math.min(...prior.map((d) => d.tokens));
153 │ }
154 │ 
155 │ /** Projected tokens “so far today” from the 7-day min baseline. */
156 │ export function projectTodayTokens(
157 │   days: readonly { date: string; tokens: number }[],
158 │   now: Date,
159 │   timeZone: string,
160 │ ): { date: string; tokens: number; baseline: number } {
161 │   const today = calendarDateInTimeZone(now, timeZone);
162 │   const baseline = sevenDayMinBaseline(days, today);
163 │   const tokens = Math.round(baseline * dayFractionElapsed(now, timeZone));
164 │   return { date: today, tokens, baseline };
165 │ }
166 │ 
167 │ /** Cacheable history through the payload’s last published day (no live today). */
168 │ export function materializeHistory(payload: AiActivityPayload): AiActivity {
169 │   const timeZone = payload.timezone || AI_ACTIVITY_TIMEZONE;
170 │   const history = [...payload.days].sort((a, b) =>
171 │     a.date.localeCompare(b.date),
172 │   );
173 │   const endHistory = history.at(-1)!.date;
174 │ 
175 │   return buildAiActivity(fillSparseDailySeries(history, endHistory, 364), {
176 │     generatedAt: payload.generatedAt,
177 │     timezone: timeZone,
178 │     lifetimeTokens: payload.lifetimeTokens,
179 │   });
180 │ }
181 │ 
182 │ /** Window kept for display: one year of consecutive days ending today. */
183 │ export const ACTIVITY_WINDOW_DAYS = 365;
184 │ 
185 │ /**
186 │  * Extend the history to today. Two rules keep the grid honest:
187 │  *
188 │  * 1. Days between the last published day and today are filled, never skipped —
189 │  *    the series must stay consecutive or every cell lands on the wrong weekday.
190 │  *    They are filled as *unrecorded*, not as zero: the feed did not report a
191 │  *    quiet day, it did not report at all.
192 │  * 2. Today is projected only when the payload is fresh (published through
193 │  *    yesterday). A stale feed means no data, and no data is drawn as an empty
194 │  *    slot, not as a guess from month-old numbers.
195 │  *
196 │  * Lifetime stays the published nightly total (excludes synthetic today).
197 │  */
198 │ export function withLiveToday(history: AiActivity, now = new Date()): AiActivity {
199 │   const timeZone = history.timezone;
200 │   const today = calendarDateInTimeZone(now, timeZone);
201 │   const lastPublished = history.days.at(-1)?.date ?? "";
202 │   // Avoid duplicating the last published day if clocks briefly disagree.
203 │   if (!lastPublished || today <= lastPublished) return history;
204 │ 
205 │   const fresh = shiftYmd(today, -1) <= lastPublished;
206 │   const max = Math.max(0, ...history.days.map((d) => d.tokens));
207 │ 
208 │   const appended: ActivityDay[] = [];
209 │   for (
210 │     let cursor = shiftYmd(lastPublished, 1);
211 │     cursor <= today;
212 │     cursor = shiftYmd(cursor, 1)
213 │   ) {
214 │     if (cursor === today && fresh) {
215 │       const projection = projectTodayTokens(history.days, now, timeZone);
216 │       appended.push({
217 │         date: today,
218 │         tokens: projection.tokens,
219 │         intensity: intensityFromTokens(projection.tokens, max),
220 │         live: true,
221 │       });
222 │     } else {
223 │       appended.push({ date: cursor, tokens: 0, intensity: 0, recorded: false });
224 │     }
225 │   }
226 │ 
227 │   return {
228 │     days: [...history.days, ...appended].slice(-ACTIVITY_WINDOW_DAYS),
229 │     lifetimeTokens: history.lifetimeTokens,
230 │     generatedAt: history.generatedAt,
231 │     timezone: history.timezone,
232 │   };
233 │ }
234 │ 
235 │ export function materializeAiActivity(
236 │   payload: AiActivityPayload,
237 │   now = new Date(),
238 │   options?: { includeLiveToday?: boolean },
239 │ ): AiActivity {
240 │   const history = materializeHistory(payload);
241 │   if (options?.includeLiveToday === false) return history;
242 │   return withLiveToday(history, now);
243 │ }
