 17 │   recorded?: false;
 18 │ };
 19 │ 
 20 │ export type Intensity = 0 | 1 | 2 | 3 | 4;
 21 │ 
 22 │ export type ActivityDay = DailyTokens & {
 23 │   intensity: Intensity;
 24 │   /** Synthetic “live” projection for the current local day. */
 25 │   live?: boolean;
