 27 │ 
 28 │ export type AiActivity = {
 29 │   days: ActivityDay[];
 30 │   lifetimeTokens: number;
 31 │   /** ISO timestamp of the nightly payload, when known. */
 32 │   generatedAt: string | null;
 33 │   timezone: string;
