 88 │ export function buildAiActivity(
 89 │   series: readonly DailyTokens[],
 90 │   options?: {
 91 │     liveDate?: string;
 92 │     generatedAt?: string | null;
 93 │     timezone?: string;
 94 │     /** Authoritative lifetime from the payload (preferred over series sum). */
 95 │     lifetimeTokens?: number;
 96 │   },
 97 │ ): AiActivity {
 98 │   const max = Math.max(0, ...series.map((d) => d.tokens));
 99 │   const liveDate = options?.liveDate;
100 │ 
101 │   const days: ActivityDay[] = series.map((day) => ({
102 │     ...day,
103 │     intensity: intensityFromTokens(day.tokens, max),
104 │     live: liveDate === day.date ? true : undefined,
105 │   }));
106 │ 
107 │   const seriesSum = series.reduce((sum, day) => sum + day.tokens, 0);
108 │   const lifetimeTokens =
109 │     options?.lifetimeTokens !== undefined
110 │       ? options.lifetimeTokens
111 │       : seriesSum;
112 │ 
113 │   return {
114 │     days,
115 │     lifetimeTokens,
116 │     generatedAt: options?.generatedAt ?? null,
117 │     timezone: options?.timezone ?? AI_ACTIVITY_TIMEZONE,
118 │   };
119 │ }
