10 │ 
11 │ export type ActivityWeek = {
12 │   /** ISO date of the week's Sunday-aligned first slot. */
13 │   key: string;
14 │   /** Present only on the week that opens a new month. */
15 │   monthLabel?: string;
16 │   /** Sunday → Saturday. `null` pads the partial first and last weeks. */
17 │   cells: (ActivityDay | null)[];
18 │ };
19 │ 
20 │ /** Day of week (0 = Sunday) for a YYYY-MM-DD calendar date. */
21 │ export function weekdayIndex(date: string): number {
22 │   const [y, m, d] = date.split("-").map(Number);
23 │   return new Date(Date.UTC(y!, m! - 1, d!, 12)).getUTCDay();
24 │ }
25 │ 
26 │ export function monthAbbreviation(date: string): string {
27 │   const [y, m, d] = date.split("-").map(Number);
28 │   return new Intl.DateTimeFormat("en-US", {
29 │     month: "short",
30 │     timeZone: "UTC",
31 │   }).format(new Date(Date.UTC(y!, m! - 1, d!, 12)));
32 │ }
33 │ 
34 │ /** Long, human date for readouts and cell labels: "Sat, Aug 3, 2026". */
35 │ export function formatActivityDate(date: string): string {
36 │   const [y, m, d] = date.split("-").map(Number);
37 │   return new Intl.DateTimeFormat("en-US", {
38 │     weekday: "short",
39 │     month: "short",
40 │     day: "numeric",
41 │     year: "numeric",
42 │     timeZone: "UTC",
43 │   }).format(new Date(Date.UTC(y!, m! - 1, d!, 12)));
44 │ }
45 │ 
46 │ /**
47 │  * Chunk a consecutive day series into Sunday-aligned weeks, padding the
48 │  * partial weeks at both ends so every column is exactly seven slots tall.
49 │  * A month label is attached to the first week that opens a new month, and
50 │  * never to the final week (there is no room to render it).
51 │  */
52 │ export function buildActivityWeeks(
53 │   days: readonly ActivityDay[],
54 │ ): ActivityWeek[] {
55 │   if (days.length === 0) return [];
56 │ 
57 │   const weeks: ActivityWeek[] = [];
58 │   let cells: (ActivityDay | null)[] = new Array(weekdayIndex(days[0]!.date)).fill(
59 │     null,
60 │   );
61 │ 
62 │   for (const day of days) {
63 │     cells.push(day);
64 │     if (cells.length === 7) {
65 │       weeks.push({ key: cells.find(Boolean)!.date, cells });
66 │       cells = [];
67 │     }
68 │   }
69 │   if (cells.length > 0) {
70 │     weeks.push({
71 │       key: cells.find(Boolean)!.date,
72 │       cells: [...cells, ...new Array(7 - cells.length).fill(null)],
73 │     });
74 │   }
75 │ 
76 │   let labelled = "";
77 │   weeks.forEach((week, index) => {
78 │     // The last column has no horizontal room for a label.
79 │     if (index === weeks.length - 1) return;
80 │     const first = week.cells.find(Boolean);
81 │     if (!first) return;
82 │     const month = first.date.slice(0, 7);
83 │     if (month === labelled) return;
84 │     labelled = month;
85 │     // Skip a label that would collide with the previous one on a stub week.
86 │     if (index === 0 && week.cells[0] === null) return;
87 │     week.monthLabel = monthAbbreviation(first.date);
88 │   });
89 │ 
90 │   return weeks;
91 │ }

   Activity mosaic. Fixed 12px blocks on a 2px gutter, square corners — the
   grid is a measuring instrument, so its cells are not decorated. Intensity
   is carried by the neutral foreground at five opacities.
--------------------------------------------------------------------------- */

.activity-grid {
  --cell-size: 12px;
  --cell-gap: 2px;
  display: grid;
  grid-template-columns: repeat(var(--weeks, 53), var(--cell-size));
  gap: var(--cell-gap);
  width: max-content;
  /* The grid is one tab stop, but the thing that moves is the active cell, so
     the ring is drawn there instead of around all 365 of them. */
  outline: none;
  /* Room for that ring and for the live cell's 2px halo, so neither can cross
     the panel's vertical rail. */
  padding-inline: 3px;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, var(--cell-size));
  gap: var(--cell-gap);
  padding-top: 1.05rem;
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  pointer-events: none;
}

/* The strip is 742px of year on a 372px phone, so it is dragged rather than
   trimmed. The edge fades are driven by the scroll position itself: each side
   is masked only while there is more grid past it, so a strip that fits shows
   no fade at all and a strip scrolled to its end stops advertising an end. */
@property --activity-fade-s {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@property --activity-fade-e {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@keyframes activity-fade-s {
  from {
    --activity-fade-s: 0px;
  }
  to {
    --activity-fade-s: var(--activity-fade);
  }
}
@keyframes activity-fade-e {
  from {
    --activity-fade-e: var(--activity-fade);
  }
  to {
    --activity-fade-e: 0px;
  }
}

.activity-scroll {
  --activity-fade: 2.5rem;
  display: flex;
  /* The same gutter every other row in the panel keeps, so the first and last
     week line up with the caption above them rather than with the rail. */
  padding-inline: 1rem;
  /* Centred while the year fits the rail, flush-left once it does not —
     `safe` is what keeps the first week reachable instead of centring it off
     the scrollable edge. */
  justify-content: safe center;
  overflow-x: auto;
  overflow-y: hidden;
  /* The grid is a drawing; a scrollbar drawn under it would read as part of
     the figure. The strip still scrolls by drag, wheel and keyboard. */
  scrollbar-width: none;
  mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 var(--activity-fade-s),
    #000 calc(100% - var(--activity-fade-e)),
    transparent 100%
  );
  animation:
    activity-fade-s 1ms linear both,
    activity-fade-e 1ms linear both;
  animation-timeline: scroll(self inline), scroll(self inline);
