     export type DailyTokens = { date: string; tokens: number };
     export type Intensity = 0 | 1 | 2 | 3 | 4;
     export type ActivityDay = DailyTokens & { intensity: Intensity };
     export type AiActivity = { days: ActivityDay[]; lifetimeTokens: number; timezone: string };
     export type AiActivitySource = "blob" | "fallback";

     export type IntensityThresholds = readonly [number, number, number];
     export function quartileThresholds(days: readonly DailyTokens[]): IntensityThresholds {
       const positive = days.map((d) => d.tokens).filter((t) => t > 0).sort((a, b) => a - b);
       if (positive.length === 0) return [0, 0, 0];
       const at = (ratio: number) =>
         positive[Math.min(positive.length - 1, Math.floor(positive.length * ratio))]!;
       return [at(0.25), at(0.5), at(0.75)];
     }
     export function intensityFromTokens(tokens: number, thresholds: IntensityThresholds): Intensity {
       if (tokens <= 0) return 0;
       if (tokens <= thresholds[0]) return 1;
       if (tokens <= thresholds[1]) return 2;
       if (tokens <= thresholds[2]) return 3;
       return 4;
     }

     export const ACTIVITY_MAX_MONTHS = 12;
     export const ACTIVITY_MIN_MONTH_RATIO = 0.25;
     function daysInMonth(date: string): number {
       const [y, m] = date.split("-").map(Number);
       return new Date(Date.UTC(y!, m!, 0)).getUTCDate();
     }
     export function activityWindowStart(days, today, maxMonths = ACTIVITY_MAX_MONTHS): string {
       const activeDays = new Map<string, number>();
       for (const day of days) {
         if (day.tokens <= 0) continue;
         const month = day.date.slice(0, 7);
         activeDays.set(month, (activeDays.get(month) ?? 0) + 1);
       }
       let start = startOfMonth(today);
       for (let back = 1; back < maxMonths; back++) {
         const month = shiftMonth(today, -back);
         const needed = Math.ceil(daysInMonth(month) * ACTIVITY_MIN_MONTH_RATIO);
         if ((activeDays.get(month.slice(0, 7)) ?? 0) < needed) break;
         start = month;
       }
       return start;
     }

